ON CONFLICT(slug) DO UPDATE SET category = excluded.category, brand = excluded.brand, name_en = excluded.name_en,
  name_ru = excluded.name_ru, desc_en = excluded.desc_en, desc_ru = excluded.desc_ru, price_aed = excluded.price_aed,
  old_price_aed = NULL, volume_ml = excluded.volume_ml, abv = excluded.abv, origin = excluded.origin, image = excluded.image,
  featured = excluded.featured, active = 1, updated_at = datetime('now');
